import 'package:intl/intl.dart' show DateFormat;
import 'logic.dart';

/// Worker app languages (the staff app stays Arabic). A worker's language defaults from their nationality
/// and can be changed on the account tab (kept in the auth user's metadata).
const workerLangs = {'ar': 'العربية', 'en': 'English', 'ur': 'اردو', 'hi': 'हिन्दी', 'bn': 'বাংলা', 'ne': 'नेपाली'};
const rtlLangs = {'ar', 'ur'};

String defaultLang(Json worker) => switch (str(worker['nat'])) {
      'هندي' => 'hi',
      'باكستاني' => 'ur',
      'بنغلاديشي' => 'bn',
      'نيبالي' => 'ne',
      'فلبيني' => 'en',
      _ => 'ar',
    };

String lang = 'ar';

/// Translated text for [key]; `{n}` is replaced by [n]. Falls back to English, then Arabic.
String tr(String key, [Object? n]) {
  final s = _t[lang]?[key] ?? _t['en']![key] ?? _t['ar']![key] ?? key;
  return n == null ? s : s.replaceAll('{n}', '$n');
}

